From 66b956207e97614132fa15707a44412ab8f695fc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:56:24 +0100
Subject: [PATCH] applets/kicker: import default favorites only once per user

Every new launcher with an empty favorites list imported the default
favorites again, even if the user had removed them on purpose. Skip the
import when a launcher has already stored favorites for this user.

BUG: 522392
---
 applets/kicker/kastatsfavoritesmodel.cpp | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/applets/kicker/kastatsfavoritesmodel.cpp b/applets/kicker/kastatsfavoritesmodel.cpp
index 224337a54c..275537f4de 100644
--- a/applets/kicker/kastatsfavoritesmodel.cpp
+++ b/applets/kicker/kastatsfavoritesmodel.cpp
@@ -608,6 +608,14 @@ void KAStatsFavoritesModel::portOldFavorites(const QStringList &_ids)
     if (!d)
         return;

+    // Favorites are shared by all launchers, so only the first one imports the defaults
+    const auto statsConfig = KSharedConfig::openConfig(u"kactivitymanagerd-statsrc"_s);
+    if (std::ranges::any_of(statsConfig->groupList(), [](const QString &group) {
+            return group.contains(u".favorites.instance-");
+        })) {
+        return;
+    }
+
     KConfig config(u"kicker-extra-favoritesrc"_s);
     auto group = config.group(u"General"_s);
     auto prepend = group.readXdgListEntry("Prepend", QStringList());
-- 
